var total_cards_picked_up: int = 0

func pick_up(count: int) -> void:
    total_cards_picked_up += count
    for _ in range(count):
        if GameState.deck.size() > 0:
            GameState.hands[GameState.current_player].append(GameState.deck.pop_back())

